    print(f'Available columns: {available_columns}')
except Exception as e:
    print(f'Error getting columns: {e}')
    available_columns = []
assignment_col = None
for col in available_columns:
    if 'Assignment' in col and 'History' in col:
        assignment_col = col
        break
if assignment_col is None:
    result = {'type': 'string', 'value': 'No assignment history column found in the database schema.'}
else:
    query = f"""
        SELECT 
            "[Employee Master[Employee Name]]" AS employee_name,
            rec['Employee Assignment History[Assignment Name]'] AS assignment_name,
            rec['Employee Assignment History[Position Title]'] AS position_title
        FROM enterprise_data, 
             UNNEST("{assignment_col}") AS t(rec)
    """
    df = execute_sql_query(query)
    if df.empty or len(df) == 0:
        result = {'type': 'string', 'value': 'No assignment history records found in the database.'}
    else:
        df = df[df['assignment_name'].astype(str).str.strip().ne('') & df['assignment_name'].notnull()]
        df = df[df['position_title'].astype(str).str.strip().ne('') & df['position_title'].notnull()]
        if df.empty:
            result = {'type': 'string', 'value': 'No valid assignment history records found.'}
        else:
            result_lines = []
            result_lines.append('=' * 80)
            result_lines.append('EMPLOYEE ASSIGNMENT HISTORY')
            result_lines.append('=' * 80)
            result_lines.append('')
            employee_names = df['employee_name'].unique().tolist()
            for emp_name in sorted(employee_names):
                emp_df = df[df['employee_name'] == emp_name]
                emp_name_str = str(emp_name).strip() if pd.notna(emp_name) else 'Unknown'
                result_lines.append(f'Employee: {emp_name_str}')
                result_lines.append('-' * 60)
                assignment_list = []
                for _, row in emp_df.iterrows():
                    assignment = str(row['assignment_name']).strip() if pd.notna(row['assignment_name']) else 'Unknown'
                    position = str(row['position_title']).strip() if pd.notna(row['position_title']) else 'Unknown'
                    if assignment and assignment != 'Unknown' and assignment != '':
                        assignment_list.append((assignment, position))
                if assignment_list:
                    for i, (assignment, position) in enumerate(assignment_list, 1):
                        result_lines.append(f'  {i}. Assignment: {assignment}')
                        result_lines.append(f'     Position: {position}')
                else:
                    result_lines.append('  No assignments found for this employee.')
                result_lines.append('')
                result_lines.append('-' * 60)
            result_lines.append('')
            result_lines.append(f'Total Employees with Assignments: {len(employee_names)}')
            result_lines.append('=' * 80)
            result = {'type': 'string', 'value': '\n'.join(result_lines)}
result = {'type': 'string', 'value': result.get('value', 'No data available for the requested query.')}
